import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        int base = Integer.parseInt(input[0]);
        int number = Integer.parseInt(input[1]);
        boolean isOk = true;
        Deque<Integer> dequeDigits = new ArrayDeque<>();
        while (number != 0) {
            dequeDigits.addFirst(number % base);
            number /= base;
        }
        int index = 0;
        for (Integer digit : dequeDigits) {
            if (digit == 0 || digit == 1) {
                index++;
                continue;
            }
            if (digit == base - 1) {
                int j = index + 1;
                Object[] arr = dequeDigits.toArray();
                while (j < arr.length) {
                    int val = (int) arr[j];
                    if (val == base - 1) {
                        dequeDigits.remove(j);
                        dequeDigits.add(j, 0);
                    } else {
                        dequeDigits.remove(j);
                        dequeDigits.add(j, val + 1);
                        break;
                    }
                    j++;
                }
            } else {
                isOk = false;
                break;
            }
        }
        System.out.println(isOk ? "YES" : "NO");
    }
}
