#include <iostream>
#include <vector>
#include <deque>

int main() {
    int base, number;
    std::cin >> base >> number;
    bool isOk = true;
    std::deque<int> dequeDigits;

    while (number != 0) {
        dequeDigits.push_front(number % base);
        number /= base;
    }

    int index = 0;
    for (size_t i = 0; i < dequeDigits.size(); ++i) {
        int digit = dequeDigits[i];
        if (digit == 0 || digit == 1) {
            index++;
            continue;
        }
        if (digit == base - 1) {
            int j = index + 1;
            while (j < (int)dequeDigits.size()) {
                int val = dequeDigits[j];
                if (val == base - 1) {
                    dequeDigits.erase(dequeDigits.begin() + j);
                    dequeDigits.insert(dequeDigits.begin() + j, 0);
                } else {
                    dequeDigits.erase(dequeDigits.begin() + j);
                    dequeDigits.insert(dequeDigits.begin() + j, val + 1);
                    break;
                }
                j++;
            }
        } else {
            isOk = false;
            break;
        }
        index++;
    }

    std::cout << (isOk ? "YES" : "NO") << std::endl;
    return 0;
}

